/// Default bpffs directory under which per-interface map pins are created.
pub const DEFAULT_BPFFS_PIN_ROOT: &str = "/sys/fs/bpf/opc-gtpu";
/// Default tc filter priority for the datapath programs.
pub const DEFAULT_TC_PRIORITY: u16 = 50;
/// Maximum number of managed-device identities returned by one inventory.
///
/// The backend always returns the identities with the lowest interface
/// indexes, in ascending order. Callers must inspect
/// [`EbpfManagedDeviceInventory::completeness`] before treating absence from
/// the returned slice as evidence that a device is unmanaged.
pub const MAX_EBPF_MANAGED_DEVICE_IDENTITIES: usize = 64;

/// Whether a managed-device inventory contains the complete registry.
#[non_exhaustive]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum EbpfManagedDeviceInventoryCompleteness {
    /// Every managed-device identity is present.
    Complete,
    /// More identities existed than the public inventory bound permits.
    Truncated,
}

impl EbpfManagedDeviceInventoryCompleteness {
    /// Return whether identities were omitted by the inventory bound.
    #[must_use]
    pub const fn is_truncated(self) -> bool {
        matches!(self, Self::Truncated)
    }
}

impl fmt::Display for EbpfManagedDeviceInventoryCompleteness {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(match self {
            Self::Complete => "complete",
            Self::Truncated => "truncated",
        })
    }
}

/// Exact public identity of one device managed by an eBPF backend instance.
///
/// The identity intentionally contains only the interface name and index. Its
/// formatting implementations redact both values; consumers that need to
/// compare an authoritative [`GtpDevice`] should use [`Self::matches_device`].
#[derive(Clone, PartialEq, Eq, Hash)]
pub struct EbpfManagedDeviceIdentity {
    name: String,
    ifindex: u32,
}

impl EbpfManagedDeviceIdentity {
    /// Return the managed interface name.
    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }

    /// Return the managed interface index.
    #[must_use]
    pub const fn ifindex(&self) -> u32 {
        self.ifindex
    }

    /// Return whether both fields exactly match `device`.
    ///
    /// A name-only or index-only match is deliberately insufficient: either
    /// mismatch means the caller does not hold the identity represented by
    /// this inventory entry.
    #[must_use]
    pub fn matches_device(&self, device: &GtpDevice) -> bool {
        self.ifindex == device.ifindex && self.name == device.name
    }
}

impl fmt::Debug for EbpfManagedDeviceIdentity {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("EbpfManagedDeviceIdentity")
            .field("interface_identity", &"<redacted>")
            .finish()
    }
}

impl fmt::Display for EbpfManagedDeviceIdentity {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("managed eBPF GTP-U device identity")
    }
}

/// Bounded, read-only view of the devices managed by one eBPF backend.
///
/// Identities are ordered by ascending interface index. The slice contains at
/// most [`MAX_EBPF_MANAGED_DEVICE_IDENTITIES`] entries and grants no authority
/// to mutate a device, pinned object, map, program, or session.
#[derive(Clone, PartialEq, Eq)]
pub struct EbpfManagedDeviceInventory {
    identities: Box<[EbpfManagedDeviceIdentity]>,
    completeness: EbpfManagedDeviceInventoryCompleteness,
}

impl EbpfManagedDeviceInventory {
    /// Return the deterministically ordered managed identities.
    #[must_use]
    pub fn identities(&self) -> &[EbpfManagedDeviceIdentity] {
        &self.identities
    }

    /// Return whether the bounded result is complete or truncated.
    #[must_use]
    pub const fn completeness(&self) -> EbpfManagedDeviceInventoryCompleteness {
        self.completeness
    }

    /// Return whether identities were omitted by the inventory bound.
    #[must_use]
    pub const fn is_truncated(&self) -> bool {
        self.completeness.is_truncated()
    }

    /// Return the number of identities in this bounded result.
    #[must_use]
    pub const fn len(&self) -> usize {
        self.identities.len()
    }

    /// Return whether this inventory contains no identities.
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.identities.is_empty()
    }

    /// Return whether a returned identity exactly matches `device`.
    ///
    /// `false` proves that the bounded result does not contain `device`; it
    /// proves the backend does not manage `device` only when
    /// [`Self::completeness`] is
    /// [`EbpfManagedDeviceInventoryCompleteness::Complete`].
    #[must_use]
    pub fn contains_device(&self, device: &GtpDevice) -> bool {
        self.identities
            .iter()
            .any(|identity| identity.matches_device(device))
    }
}

impl fmt::Debug for EbpfManagedDeviceInventory {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("EbpfManagedDeviceInventory")
            .field("identity_count", &self.identities.len())
            .field("completeness", &self.completeness)
            .finish()
    }
}

impl fmt::Display for EbpfManagedDeviceInventory {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "managed eBPF GTP-U device inventory ({} identities, {})",
            self.identities.len(),
            self.completeness
        )
    }
}

fn require_ebpf_executable_pmtu_policy(
    policy: Option<GtpuUplinkMtuPolicy>,
) -> Result<(), GtpuError> {
    if policy.is_some_and(|policy| {
        policy.fragmentation() == GtpuOuterFragmentPolicy::RequireOuterFragmentation
    }) {
        return Err(GtpuError::invalid_config(
            "device.uplink_mtu_policy.fragmentation",
            "tc eBPF cannot execute outer fragmentation; use SignalPacketTooBig",
        ));
    }
    Ok(())
}

// Off Linux the only callers are the unit tests: the map readers that consult
// this predicate live in the kernel runtime module, which is Linux-gated.
#[cfg(any(target_os = "linux", test))]
fn ebpf_pmtu_map_state_is_executable(state: UplinkMtuMapState) -> bool {
    match state {
        UplinkMtuMapState::Unset => true,
        UplinkMtuMapState::Configured(policy) => {
            policy.fragmentation() == GtpuOuterFragmentPolicy::SignalPacketTooBig
        }
        UplinkMtuMapState::Corrupt => false,
    }
}

/// Redaction-safe aggregate of one eBPF GTP-U datapath counter map.
///
/// Each value is the saturating sum of every per-CPU slot in the exact map
/// held by the backend. The counters contain no addresses, TEIDs, marks, or
/// packet contents.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct EbpfGtpuDatapathCounters {
    /// Uplink packets for which a GTP-U outer header was materialized and
    /// handed to `bpf_redirect_neigh`.
    ///
    /// This counts encapsulations *submitted for redirect*, not packets
    /// delivered to the peer. `bpf_redirect_neigh` only records the target
    /// ifindex and returns `TC_ACT_REDIRECT`; the FIB lookup, the neighbour
    /// resolution, and any resulting drop all happen afterwards in
    /// `skb_do_redirect()`, once the classifier has already returned. So an
    /// uplink that is black-holed downstream -- no route covering the outer
    /// destination, no resolvable neighbour -- still increments this counter
    /// once per subscriber packet.
    ///
    /// A rising `uplink_encapsulated` therefore proves that session lookup and
    /// encapsulation are working, and nothing more. Read it against
    /// [`Self::uplink_redirects_resolved`], which counts the frames that
    /// actually cleared route and neighbour resolution: absent the locally
    /// originated traffic that counter's third limit describes, the two rise
    /// together on a healthy uplink, and the second stops while the first keeps
    /// rising when the outer destination becomes unreachable.
    pub uplink_encapsulated: u64,
    /// Uplink packets for which no usable FAR was found.
    ///
    /// The datapath's own re-emitted outer frames are excluded. Their source
    /// is the local S2b-U address rather than a UE PAA, so before the redirect
    /// outcome was recognized this counter rose once per *successfully
    /// delivered* uplink IPv4 packet and read a healthy uplink as session-state
    /// corruption.
    ///
    /// That is the whole of the change. This is still a miss counter for every
    /// mark-zero IPv4 frame leaving the S2b-U attachment whose source is not a
    /// provisioned UE PAA, so locally originated traffic from that host still
    /// lands here -- GTP-U echo and error indication among it, which the
    /// re-entry check deliberately excludes from
    /// [`Self::uplink_redirects_resolved`] by message type. A nonzero value is
    /// a prompt to look, not by itself proof of session-state corruption.
    pub uplink_far_misses: u64,
    /// Downlink G-PDUs successfully decapsulated.
    pub downlink_decapsulated: u64,
    /// Downlink G-PDUs dropped because their TEID was unknown.
    pub downlink_unknown_teid: u64,
    /// Downlink GTP-U packets dropped as malformed.
    pub downlink_malformed: u64,
    /// Downlink G-PDUs dropped because the inner destination did not match
    /// the PDR's UE address.
    pub downlink_destination_mismatches: u64,
    /// Downlink G-PDUs dropped because binding state was missing or corrupt.
    pub downlink_binding_invalid: u64,
    /// Downlink G-PDUs dropped for an outer address-family mismatch.
    pub downlink_binding_family_mismatches: u64,
    /// Downlink G-PDUs dropped for an unauthorized outer peer.
    pub downlink_binding_peer_mismatches: u64,
    /// Downlink G-PDUs dropped for an unauthorized local outer destination.
    pub downlink_binding_local_mismatches: u64,
    /// Downlink G-PDUs dropped on the wrong ingress attachment.
    pub downlink_binding_ingress_mismatches: u64,
    /// Downlink G-PDUs dropped by the explicit UDP source-port policy.
    pub downlink_binding_source_port_mismatches: u64,
    /// Uplink packets rejected fail closed by the effective-MTU policy
    /// (over-MTU without outer-fragment permission).
    pub uplink_mtu_rejected: u64,
    /// Uplink packets dropped because the persisted MTU policy bytes were
    /// corrupt. A canary for external writers: nonzero always means non-SDK
    /// mutation of adopted state.
    pub uplink_mtu_policy_corrupt: u64,
    /// Encapsulated uplink frames whose neighbour redirect actually resolved.
    ///
    /// A successful `bpf_redirect_neigh` puts the frame back on the same tc
    /// egress hook (`skb_do_redirect` -> `__bpf_redirect_neigh_v4` ->
    /// `bpf_out_neigh_v4` -> `neigh_output` -> `dev_queue_xmit` ->
    /// `sch_handle_egress`); a redirect that finds no usable route is freed
    /// before it gets there. The datapath recognizes its own re-emitted outer
    /// frame on that second traversal, so this counter is the redirect outcome
    /// that the helper's return value -- a constant `TC_ACT_REDIRECT` at this
    /// call shape -- can never report.
    ///
    /// Three honest limits:
    ///
    /// - It proves the frame cleared FIB and neighbour resolution and reached
    ///   `dev_queue_xmit`. It does not prove the peer received it; a later
    ///   qdisc, driver, or on-wire loss is still invisible from inside the
    ///   program.
    /// - An unresolved neighbour *lags* rather than reads wrong. The skb waits
    ///   in the neighbour's `arp_queue` and is counted late if resolution
    ///   eventually succeeds, and never if it does not.
    /// - It is **unauthenticated**. The discriminator is the frame itself, so
    ///   any locally originated packet of the same shape -- outer source equal
    ///   to this attachment's own S2b-U endpoint, UDP/2152, a GTPv1 G-PDU
    ///   header -- increments it too, and an unprivileged co-located process
    ///   can send one. Nothing else is affected: no forwarding decision reads
    ///   this counter. Tightening cannot close it either, because every
    ///   discriminator available in-program is in-band and so forgeable by a
    ///   local sender. Trust the value only as far as the host is trusted.
    ///
    /// `uplink_encapsulated` rising while this stays flat is the signature of
    /// a total uplink outage caused downstream of the classifier.
    pub uplink_redirects_resolved: u64,
}

/// Identity-bound diagnostic snapshot for one live eBPF GTP-U datapath.
///
/// Under the backend's exclusive-writer contract, a successful snapshot proves
/// that both tc hooks contain the exact program IDs loaded by this backend,
/// every named bpffs pin identifies the exact held map, and both programs
/// reference `counters_map_id` at both identity checks. The program and map IDs
/// are kernel-local diagnostic handles and the counters are aggregate-only, so
/// `Debug` is safe for redacted operational evidence.
///
/// # Counter identity and re-baselining
///
/// Each counter map ID — `counters_map_id`,
/// `downlink_binding_counters_map_id` and `uplink_pmtu_counters_map_id` —
/// identifies the exact kernel map the published counters were read from. A
/// rebuilt map starts at zero, and it is a different map, so its ID differs
/// from the one it replaced.
///
/// On an identity change, discard prior deltas and re-baseline from the new
/// value. Do not alert on the step: a consumer that treats these as monotonic
/// and ignores the identity will read a rebuild as either a negative delta or a
/// full-value spike, depending on which way it clamps.
///
/// An *unchanged* ID is weaker evidence than a changed one and does not prove
/// no rebuild happened. The kernel allocates map IDs from a reusable space, so
/// a rebuild can be handed an ID that a freed map previously held. Treat an
/// unexplained fall toward zero as a rebuild even when the ID is unchanged;
/// the identity is a positive signal, not a completeness guarantee.
///
/// Kernel map IDs are allocated per boot and are recycled. A baseline persisted
/// across a host reboot may therefore observe the same ID for a different map;
/// pair the ID with a boot identity if a baseline has to outlive the host.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct EbpfGtpuDatapathSnapshot {
    /// Kernel program ID attached at tc egress for uplink encapsulation.
    pub uplink_program_id: u32,
    /// Kernel program ID attached at tc ingress for downlink decapsulation.
    pub downlink_program_id: u32,
    /// Kernel map ID of the exact pinned per-CPU counter map.
    pub counters_map_id: u32,
    /// Kernel map ID of the exact pinned binding-drop counter map.
    pub downlink_binding_counters_map_id: u32,
    /// Kernel map ID of the exact pinned uplink MTU-drop counter map.
    ///
    /// Published for the same reason as the other two: this map's counters are
    /// read into the snapshot, so a consumer needs its identity to tell a
    /// rebuild from a drop to zero.
    pub uplink_pmtu_counters_map_id: u32,
    /// Per-path counters aggregated across all possible CPUs.
    pub counters: EbpfGtpuDatapathCounters,
}

/// Runtime behavior for the eBPF GTP-U backend.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EbpfGtpuDataplaneBackendConfig {
    /// bpffs directory under which per-interface pin directories are created.
    pub bpffs_pin_root: PathBuf,
    /// tc filter priority used when attaching the clsact programs.
    pub tc_priority: u16,
}

impl Default for EbpfGtpuDataplaneBackendConfig {
    fn default() -> Self {
        Self {
            bpffs_pin_root: PathBuf::from(DEFAULT_BPFFS_PIN_ROOT),
            tc_priority: DEFAULT_TC_PRIORITY,
        }
    }
}

/// Environment capability report produced by the runtime for [`GtpuProbe`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub(crate) struct EbpfEnvironment {
    /// The platform can run the eBPF datapath at all.
    pub platform_supported: bool,
    /// bpffs is available for map pinning.
    pub bpffs_present: bool,
    /// Kernel BTF is exposed at `/sys/kernel/btf/vmlinux`.
    pub btf_present: bool,
    /// `CAP_NET_ADMIN` is effective (tc attach).
    pub net_admin_capable: bool,
    /// `CAP_BPF` or `CAP_SYS_ADMIN` is effective (program/map load).
    pub bpf_capable: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum EbpfAttachmentDisposition {
    // Only a real tc attach reports a freshly created filter, so off Linux
    // this variant is produced by the fake runtimes in the unit tests alone.
    #[cfg(any(target_os = "linux", test))]
    Fresh,
    Retained,
}

/// Result of adopting a retained graph for cleanup only.
///
/// This never attaches forwarding programs. A successful adoption leaves the
/// graph's tc hooks fenced (detached if they were live) or already absent, so
/// forwarding stays disabled while the caller reads back and removes stale PDP
/// contexts.
///
/// Cleanup-only recovery is an eBPF datapath feature, so the adoption result is
/// only constructed by the Linux kernel runtime and the test fake.
#[cfg(any(target_os = "linux", test))]
#[derive(Clone, Copy, PartialEq, Eq)]
pub(crate) enum EbpfCleanupOnlyAdoption {
    /// The retained graph was adopted for cleanup only.
    Adopted {
        /// The recorded local S2b-U IPv4 of the retained graph.
        local_ip: [u8; 4],
        /// True when at least one live hook owned by the graph was detached
        /// (fenced) during adoption; false when both hooks were already absent.
        hooks_fenced: bool,
    },
    /// No retained graph exists, the reserved hook slots are empty, and the
    /// all-placement SDK hook inventory is empty. Nothing was manufactured to
    /// prove absence.
    Absent,
    /// Adoption authority was not granted. An indeterminate refusal can follow
    /// a partially completed hook fence and therefore requires re-observation.
    Refused(RetainedGraphCleanupRefusal),
}

#[cfg(any(target_os = "linux", test))]
impl fmt::Debug for EbpfCleanupOnlyAdoption {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Adopted { hooks_fenced, .. } => formatter
                .debug_struct("Adopted")
                .field("local_ip", &"<redacted-local-endpoint>")
                .field("hooks_fenced", hooks_fenced)
                .finish(),
            Self::Absent => formatter.write_str("Absent"),
            Self::Refused(refusal) => formatter.debug_tuple("Refused").field(refusal).finish(),
        }
    }
}

/// Classify deterministic retained-content failures without collapsing
/// observation or mutation I/O into structural damage.
///
/// These two operation labels are emitted only by local invariant closures
/// after typed map access succeeds. Every kernel/map access failure remains an
/// ordinary error and is surfaced by cleanup acquisition as retryable
/// indeterminate state.
#[cfg(any(target_os = "linux", test))]
fn cleanup_only_content_failure(error: GtpuError) -> Result<EbpfCleanupOnlyAdoption, GtpuError> {
    match error {
        GtpuError::StateIndeterminate {
            operation: "ebpf_pdp_recovery" | "ebpf_marked_owner_rebuild",
        } => Ok(EbpfCleanupOnlyAdoption::Refused(
            RetainedGraphCleanupRefusal::NotCurrentSchema,
        )),
        error => Err(error),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CurrentRecoveryManagedState {
    Clear,
    Conflict,
    Indeterminate,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum EbpfMapUpdateMode {
    /// Insert only when the key is absent.
    NoExist,
    /// Replace only when the key already exists.
    Exist,
}

/// Fixed, redaction-safe capacity evidence for the shared-SA TFT filter map.
///
/// The raw map never stores more than the ABI-declared bound, but callers
/// still need an exact preflight count before staging an inactive bank. This
/// type intentionally exposes no keys, values, owners, or device identity.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(crate) struct EbpfTftFilterMapCapacity {
    occupied: u32,
    maximum: u32,
}

impl EbpfTftFilterMapCapacity {
    #[cfg(any(target_os = "linux", test))]
    const fn new(occupied: u32, maximum: u32) -> Option<Self> {
        if maximum != 0 && occupied <= maximum {
            Some(Self { occupied, maximum })
        } else {
            None
        }
    }

    const fn occupied(self) -> u32 {
        self.occupied
    }

    const fn maximum(self) -> u32 {
        self.maximum
    }
}

impl fmt::Debug for EbpfTftFilterMapCapacity {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("EbpfTftFilterMapCapacity")
            .field("occupied", &self.occupied)
            .field("maximum", &self.maximum)
            .finish()
    }
}

/// Opaque authority derived from the exact retained current map/program graph.
///
/// This is deliberately private and has no formatting implementation: it is
/// map state, never subscriber state, and must not escape diagnostics.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(crate) struct EbpfTftAuthority {
    owner: [u8; 16],
    owner_generation: u64,
}

type EbpfTftFilterRecord = (
    [u8; TFT_CLASSIFIER_FILTER_KEY_LEN],
    [u8; TFT_CLASSIFIER_FILTER_VALUE_LEN],
);

#[derive(Clone, PartialEq, Eq, Default)]
pub(crate) struct EbpfSessionIndexInventory {
    uplink: Vec<(
        [u8; GTPU_SESSION_UPLINK_KEY_LEN],
        [u8; GTPU_SESSION_GROUP_REF_LEN],
    )>,
    downlink: Vec<(
        [u8; GTPU_SESSION_DOWNLINK_KEY_LEN],
        [u8; GTPU_SESSION_GROUP_REF_LEN],
    )>,
}

impl fmt::Debug for EbpfSessionIndexInventory {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("EbpfSessionIndexInventory")
            .field("uplink_count", &self.uplink.len())
            .field("downlink_count", &self.downlink.len())
            .finish()
    }
}

/// Narrow synchronous port to the kernel eBPF machinery.
///
/// The production implementation loads the committed CO-RE object with `aya`,
/// attaches tc clsact filters, and performs BPF map operations. Tests supply
/// a deterministic fake.
#[cfg_attr(not(target_os = "linux"), allow(dead_code))]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum SelectorNamespaceTerminalFenceState {
    Absent,
    Exact,
}

/// Opaque, affine ownership of the host-global selector control lock.
///
/// A runtime returns this only after it has revalidated the current namespace
/// binding (or proven the namespace unbound).  Keeping the value alive keeps
/// the host lock held across every synchronous grouped map read, mutation, and
/// readback in that operation.  It exposes only finalization, so the
/// enclosing backend routine is the only place that can consume the receipt.
pub(crate) trait SelectorNamespaceEffectGuard: Send {
    /// Complete the protected effect and make its result observable.  A guard
    /// drop may only release its flock; callers must not report success until
    /// this method has revalidated the current control path.
    fn finish(self: Box<Self>) -> Result<(), GtpuError>;
}

pub(crate) trait EbpfGtpuRuntime: Send + Sync + fmt::Debug {
    /// Resolve an interface index by name in the current netns.
    fn ifindex_by_name(&self, name: &str) -> Result<u32, GtpuError>;

    /// Load the datapath object, create-or-reuse pinned maps under `pin_dir`,
    /// write the local S2b-U IPv4 into the config map, ensure a clsact qdisc,
    /// and (re)attach the uplink/downlink programs.
    fn attach(
        &self,
        interface: &str,
        ifindex: u32,
        pin_dir: &Path,
        tc_priority: u16,
        local_ip: [u8; 4],
    ) -> Result<EbpfAttachmentDisposition, GtpuError>;

    /// Create or adopt the independent grouped-session schema and bind its
    /// exact stable device/endpoint authority to `ifindex`.
    fn attach_grouped(
        &self,
        interface: &str,
        ifindex: u32,
        pin_dir: &Path,
        tc_priority: u16,
        config: [u8; GTPU_SESSION_CONFIG_VALUE_LEN],
    ) -> Result<EbpfAttachmentDisposition, GtpuError>;

    /// Adopt a previously provisioned interface: reuse the pinned maps,
    /// (re)attach the programs, and return the recorded local S2b-U IPv4.
    /// Fails with [`GtpuError::NotFound`] when no prior provisioning exists.
    fn adopt(
        &self,
        interface: &str,
        ifindex: u32,
        pin_dir: &Path,
        tc_priority: u16,
    ) -> Result<[u8; 4], GtpuError>;

    /// Adopt a retained current-schema graph for cleanup only.
    ///
    /// Reuses the pinned maps and holds the host-global namespace lease, but
    /// never attaches the forwarding programs. Any retained live hook owned by
    /// this graph is fenced (detached) so forwarding is disabled before the
    /// caller removes stale PDP contexts. The expected local endpoint identity
    /// is validated against the retained config before mutation.
    #[cfg(any(target_os = "linux", test))]
    fn adopt_cleanup_only(
        &self,
        interface: &str,
        ifindex: u32,
        pin_dir: &Path,
        tc_priority: u16,
        expected_local_ip: [u8; 4],
    ) -> Result<EbpfCleanupOnlyAdoption, GtpuError>;

    /// Activate a cleanup-only managed device: attach the forwarding programs
    /// and links, transitioning it to a normal active attachment.
    #[cfg(any(target_os = "linux", test))]
    fn activate_cleanup_only(
        &self,
        interface: &str,
        ifindex: u32,
        pin_dir: &Path,
        tc_priority: u16,
    ) -> Result<EbpfAttachmentDisposition, GtpuError>;

    /// Detach the datapath programs and remove the map pins.
    fn detach(
        &self,
        interface: &str,
        ifindex: u32,
        pin_dir: &Path,
        tc_priority: u16,
    ) -> Result<(), GtpuError>;

    /// Remove an exact, empty legacy-v2 program/map graph while retaining
    /// retry-safe identity evidence across partial cleanup.
    fn teardown_drained_v2(
        &self,
        interface: &str,
        ifindex: u32,
        pin_dir: &Path,
        tc_priority: u16,
    ) -> Result<DrainedV2TeardownOutcome, GtpuError>;

    /// Recover an orphaned exact current-schema graph under a host-global
    /// pin-namespace lease.
    fn recover_orphaned_current_graph(
        &self,
        replacement: Option<(&str, u32)>,
        pin_dir: &Path,
        tc_priority: u16,
        allow_populated: bool,
        managed_state: CurrentRecoveryManagedState,
    ) -> Result<CurrentEbpfGraphRecoveryOutcome, GtpuError>;

    /// Read an uplink FAR entry.
    fn far_get(
        &self,
        ifindex: u32,
        key: [u8; 4],
    ) -> Result<Option<[u8; UPLINK_FAR_VALUE_LEN]>, GtpuError>;
    /// Insert or overwrite an uplink FAR entry.
    fn far_insert(
        &self,
        ifindex: u32,
        key: [u8; 4],
        value: [u8; UPLINK_FAR_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove an uplink FAR entry; returns whether it existed.
    fn far_remove(&self, ifindex: u32, key: [u8; 4]) -> Result<bool, GtpuError>;

    /// Read a marked uplink FAR entry.
    fn marked_far_get(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
    ) -> Result<Option<[u8; UPLINK_FAR_VALUE_LEN]>, GtpuError>;
    /// Insert or overwrite a marked uplink FAR entry.
    fn marked_far_insert(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
        value: [u8; UPLINK_FAR_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove a marked uplink FAR entry; returns whether it existed.
    fn marked_far_remove(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
    ) -> Result<bool, GtpuError>;

    /// Read an optional fixed uplink DSCP entry.
    fn dscp_get(
        &self,
        ifindex: u32,
        key: [u8; 4],
    ) -> Result<Option<[u8; UPLINK_DSCP_VALUE_LEN]>, GtpuError>;
    /// Insert or overwrite an optional fixed uplink DSCP entry.
    fn dscp_insert(
        &self,
        ifindex: u32,
        key: [u8; 4],
        value: [u8; UPLINK_DSCP_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove an optional fixed uplink DSCP entry; returns whether it existed.
    fn dscp_remove(&self, ifindex: u32, key: [u8; 4]) -> Result<bool, GtpuError>;

    /// Read an optional fixed marked-uplink DSCP entry.
    fn marked_dscp_get(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
    ) -> Result<Option<[u8; UPLINK_DSCP_VALUE_LEN]>, GtpuError>;
    /// Insert or overwrite an optional fixed marked-uplink DSCP entry.
    fn marked_dscp_insert(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
        value: [u8; UPLINK_DSCP_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove a fixed marked-uplink DSCP entry; returns whether it existed.
    fn marked_dscp_remove(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
    ) -> Result<bool, GtpuError>;

    /// Read an explicit uplink source-port policy entry.
    fn sport_get(
        &self,
        ifindex: u32,
        key: [u8; 4],
    ) -> Result<Option<[u8; UPLINK_SOURCE_PORT_VALUE_LEN]>, GtpuError>;
    /// Insert or overwrite an explicit uplink source-port policy entry.
    fn sport_insert(
        &self,
        ifindex: u32,
        key: [u8; 4],
        value: [u8; UPLINK_SOURCE_PORT_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove an explicit uplink source-port policy entry; returns whether it
    /// existed.
    fn sport_remove(&self, ifindex: u32, key: [u8; 4]) -> Result<bool, GtpuError>;

    /// Read an explicit marked-uplink source-port policy entry.
    fn marked_sport_get(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
    ) -> Result<Option<[u8; UPLINK_SOURCE_PORT_VALUE_LEN]>, GtpuError>;
    /// Insert or overwrite an explicit marked-uplink source-port policy
    /// entry.
    fn marked_sport_insert(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
        value: [u8; UPLINK_SOURCE_PORT_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove an explicit marked-uplink source-port policy entry; returns
    /// whether it existed.
    fn marked_sport_remove(
        &self,
        ifindex: u32,
        key: [u8; UPLINK_MARK_KEY_LEN],
    ) -> Result<bool, GtpuError>;

    /// Read a downlink PDR entry.
    fn pdr_get(
        &self,
        ifindex: u32,
        key: [u8; 4],
    ) -> Result<Option<[u8; DOWNLINK_PDR_VALUE_LEN]>, GtpuError>;
    /// Insert or overwrite a downlink PDR entry.
    fn pdr_insert(
        &self,
        ifindex: u32,
        key: [u8; 4],
        value: [u8; DOWNLINK_PDR_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove a downlink PDR entry; returns whether it existed.
    fn pdr_remove(&self, ifindex: u32, key: [u8; 4]) -> Result<bool, GtpuError>;

    /// Read a marked downlink PDR entry.
    fn marked_pdr_get(
        &self,
        ifindex: u32,
        key: [u8; 4],
    ) -> Result<Option<[u8; MARKED_DOWNLINK_PDR_VALUE_LEN]>, GtpuError>;
    /// Insert or overwrite a marked downlink PDR entry.
    fn marked_pdr_insert(
        &self,
        ifindex: u32,
        key: [u8; 4],
        value: [u8; MARKED_DOWNLINK_PDR_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove a marked downlink PDR entry; returns whether it existed.
    fn marked_pdr_remove(&self, ifindex: u32, key: [u8; 4]) -> Result<bool, GtpuError>;

    /// Read the canonical downlink outer-endpoint binding for a local TEID.
    fn downlink_binding_get(
        &self,
        ifindex: u32,
        key: [u8; 4],
    ) -> Result<Option<[u8; DOWNLINK_ENDPOINT_BINDING_VALUE_LEN]>, GtpuError>;
    /// Atomically insert or replace one complete downlink endpoint binding.
    fn downlink_binding_insert(
        &self,
        ifindex: u32,
        key: [u8; 4],
        value: [u8; DOWNLINK_ENDPOINT_BINDING_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove a downlink endpoint binding; returns whether it existed.
    fn downlink_binding_remove(&self, ifindex: u32, key: [u8; 4]) -> Result<bool, GtpuError>;

    /// Read a marked-bearer owner journal by `(PAA, mark)` selector.
    fn marked_owner_get(
        &self,
        ifindex: u32,
        selector: [u8; UPLINK_MARK_KEY_LEN],
    ) -> Result<Option<[u8; MARKED_BEARER_OWNER_VALUE_LEN]>, GtpuError>;
    /// Publish a canonical owner journal, enforcing local-TEID uniqueness.
    fn marked_owner_insert(
        &self,
        ifindex: u32,
        selector: [u8; UPLINK_MARK_KEY_LEN],
        value: [u8; MARKED_BEARER_OWNER_VALUE_LEN],
    ) -> Result<(), GtpuError>;
    /// Remove an exact owner journal and its in-memory TEID reservation.
    fn marked_owner_remove(
        &self,
        ifindex: u32,
        selector: [u8; UPLINK_MARK_KEY_LEN],
    ) -> Result<bool, GtpuError>;
    /// Resolve the sole journal selector reserving a local TEID.
    fn marked_owner_for_teid(
        &self,
        ifindex: u32,
        local_teid: [u8; 4],
    ) -> Result<Option<[u8; UPLINK_MARK_KEY_LEN]>, GtpuError>;

    /// Resolve the default-bearer local TEID reserved by one UE address.
    fn default_teid_for_ue(
        &self,
        ifindex: u32,
        ue_ip: [u8; 4],
    ) -> Result<Option<[u8; 4]>, GtpuError>;
    /// Resolve the sole default-bearer UE selector reserving a local TEID.
    fn default_ue_for_teid(
        &self,
        ifindex: u32,
        local_teid: [u8; 4],
    ) -> Result<Option<[u8; 4]>, GtpuError>;
    /// Reserve one exact default-bearer `(UE, local TEID)` identity.
    fn default_selector_insert(
        &self,
        ifindex: u32,
        ue_ip: [u8; 4],
        local_teid: [u8; 4],
    ) -> Result<(), GtpuError>;
    /// Release one exact default-bearer `(UE, local TEID)` identity.
    fn default_selector_remove(
        &self,
        ifindex: u32,
        ue_ip: [u8; 4],
        local_teid: [u8; 4],
    ) -> Result<bool, GtpuError>;

    /// Generate a fresh nonzero transaction token from the system CSPRNG.
    fn next_session_transaction_id(&self) -> Result<GtpuSessionTransactionId, GtpuError>;

    /// Return the opaque commitment to this exact canonical pin namespace.
    ///
    /// The runtime reads it only after a fresh host-global lock and exact
    /// managed-graph validation. The outer backend turns it into the affine
    /// bootstrap consumed by protected selector provisioning; callers never
    /// receive raw pin paths or commitment bytes.
    fn selector_namespace_pin_commitment(&self, ifindex: u32) -> Result<[u8; 32], GtpuError>;

    /// Acquire and retain the immutable durable selector-ledger binding for
    /// one attached grouped dataplane.  The returned guard keeps the
    /// host-global flock held until the complete synchronous grouped
    /// read/effect/recovery call has finished.  Durable-store work is never
    /// performed while this guard is live.
    fn acquire_selector_namespace_effect(
        &self,
        ifindex: u32,
        binding: crate::selector_namespace::GtpuSessionSelectorBackendBinding,
    ) -> Result<Box<dyn SelectorNamespaceEffectGuard>, GtpuError>;

    /// Acquire and retain the same host-global lock while proving that a
    /// grouped dataplane has no selector namespace binding.  Legacy raw
    /// read/removal uses this guard so provisioning cannot race its absence
    /// check and later map work.
    fn acquire_unbound_selector_namespace_effect(
        &self,
        ifindex: u32,
    ) -> Result<Box<dyn SelectorNamespaceEffectGuard>, GtpuError>;

    /// Provision the immutable selector marker. An absent marker may be
    /// minted only for a one-shot, freshly created active grouped graph; an
    /// existing initializing marker is accepted only for an exact stopped
    /// cleanup-only recovery graph with an empty control-map inventory.
    fn provision_selector_namespace_effect(
        &self,
        ifindex: u32,
        binding: crate::selector_namespace::GtpuSessionSelectorBackendBinding,
    ) -> Result<(), GtpuError>;

    /// Inspect the one durable terminal-fence capsule under a bounded host
    /// lock. The runtime must release that lock before returning so the
    /// selector authority can safely perform its protected-store CAS/readback.
    fn inspect_selector_namespace_decommission_fence(
        &self,
        ifindex: u32,
        binding: crate::selector_namespace::GtpuSessionSelectorBackendBinding,
        expected: Option<[u8; crate::selector_namespace::DECOMMISSION_CAPSULE_LEN]>,
    ) -> Result<SelectorNamespaceTerminalFenceState, GtpuError>;

    /// Create and exact-readback one precommitted terminal-fence capsule under
    /// a freshly acquired bounded host lock, then release that lock before
    /// returning. A different or additional capsule is an authority conflict.
    fn create_selector_namespace_decommission_fence(
        &self,
        ifindex: u32,
        binding: crate::selector_namespace::GtpuSessionSelectorBackendBinding,
        expected: [u8; crate::selector_namespace::DECOMMISSION_CAPSULE_LEN],
    ) -> Result<(), GtpuError>;

    /// Exactly read one persisted terminal-fence capsule under a freshly
    /// acquired bounded host lock, then release that lock before returning.
    fn read_selector_namespace_decommission_fence(
        &self,
        ifindex: u32,
        binding: crate::selector_namespace::GtpuSessionSelectorBackendBinding,
        expected: [u8; crate::selector_namespace::DECOMMISSION_CAPSULE_LEN],
    ) -> Result<(), GtpuError>;

    /// Read one grouped authority value.
    fn session_group_get(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<Option<[u8; GTPU_SESSION_GROUP_VALUE_LEN]>, GtpuError>;
    /// Insert or replace one complete grouped authority value.
    fn session_group_put(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
        value: [u8; GTPU_SESSION_GROUP_VALUE_LEN],
        mode: EbpfMapUpdateMode,
    ) -> Result<(), GtpuError>;
    /// Remove one grouped authority value.
    fn session_group_remove(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<bool, GtpuError>;

    /// Read one family-tagged uplink selector reference.
    fn session_uplink_get(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_UPLINK_KEY_LEN],
    ) -> Result<Option<[u8; GTPU_SESSION_GROUP_REF_LEN]>, GtpuError>;
    /// Insert or replace one family-tagged uplink selector reference.
    fn session_uplink_put(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_UPLINK_KEY_LEN],
        value: [u8; GTPU_SESSION_GROUP_REF_LEN],
        mode: EbpfMapUpdateMode,
    ) -> Result<(), GtpuError>;
    /// Remove one family-tagged uplink selector reference.
    fn session_uplink_remove(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_UPLINK_KEY_LEN],
    ) -> Result<bool, GtpuError>;

    /// Read one family-tagged downlink selector reference.
    fn session_downlink_get(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_DOWNLINK_KEY_LEN],
    ) -> Result<Option<[u8; GTPU_SESSION_GROUP_REF_LEN]>, GtpuError>;
    /// Insert or replace one family-tagged downlink selector reference.
    fn session_downlink_put(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_DOWNLINK_KEY_LEN],
        value: [u8; GTPU_SESSION_GROUP_REF_LEN],
        mode: EbpfMapUpdateMode,
    ) -> Result<(), GtpuError>;
    /// Remove one family-tagged downlink selector reference.
    fn session_downlink_remove(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_DOWNLINK_KEY_LEN],
    ) -> Result<bool, GtpuError>;

    /// Read one bounded in-flight grouped transaction journal.
    fn session_transaction_get(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<Option<[u8; GTPU_SESSION_TRANSACTION_VALUE_LEN]>, GtpuError>;
    /// Insert or replace one complete transaction journal.
    fn session_transaction_put(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
        value: [u8; GTPU_SESSION_TRANSACTION_VALUE_LEN],
        mode: EbpfMapUpdateMode,
    ) -> Result<(), GtpuError>;
    /// Remove one completed transaction journal.
    fn session_transaction_remove(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<bool, GtpuError>;

    /// Read one userspace-only selector-authority operation stamp.
    fn selector_operation_stamp_get(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<Option<[u8; GTPU_SESSION_SELECTOR_STAMP_VALUE_LEN]>, GtpuError>;
    /// Insert or replace one complete selector-authority operation stamp.
    fn selector_operation_stamp_put(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
        value: [u8; GTPU_SESSION_SELECTOR_STAMP_VALUE_LEN],
        mode: EbpfMapUpdateMode,
    ) -> Result<(), GtpuError>;
    /// Remove one terminal retired selector-authority operation stamp.
    #[allow(dead_code)]
    fn selector_operation_stamp_remove(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<bool, GtpuError>;

    /// Enumerate every selector value whose duplicated group ID names `key`.
    ///
    /// The result includes malformed values when their first sixteen bytes
    /// match, allowing userspace to fail closed rather than overlooking a
    /// corrupt owned component.
    fn session_index_inventory(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<EbpfSessionIndexInventory, GtpuError>;

    /// Prove the exact grouped schema, config, held pins, live hooks, program
    /// references, and namespace lease for this attachment. Implementations
    /// repeat exact named-map identity around schema/config/live-hook
    /// inspection.
    fn grouped_datapath_usable(
        &self,
        ifindex: u32,
        expected_config: [u8; GTPU_SESSION_CONFIG_VALUE_LEN],
    ) -> bool;

    /// Allocate one exact, nonzero traffic-observation publication ID from
    /// the retained per-attachment sequence. An indeterminate allocation is
    /// terminal: callers must not retry an ID whose durable publication is
    /// uncertain.
    fn traffic_observation_allocate_publication_id(&self, ifindex: u32) -> Result<u32, GtpuError>;

    /// Read one exact traffic-observation registration without consuming the
    /// shared event source.
    fn traffic_observation_registration_get(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<Option<[u8; GTPU_TRAFFIC_OBSERVATION_REGISTRATION_LEN]>, GtpuError>;

    /// Insert an exact traffic-observation registration with BPF_NOEXIST.
    fn traffic_observation_registration_put_noexist(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
        value: [u8; GTPU_TRAFFIC_OBSERVATION_REGISTRATION_LEN],
    ) -> Result<(), GtpuError>;

    /// Remove a registration only if its complete bytes still match.
    fn traffic_observation_registration_remove_exact(
        &self,
        ifindex: u32,
        key: [u8; GTPU_SESSION_GROUP_ID_LEN],
        value: [u8; GTPU_TRAFFIC_OBSERVATION_REGISTRATION_LEN],
    ) -> Result<bool, GtpuError>;

    /// Read the exact group bound to one opaque redirect nonce.
    fn traffic_observation_redirect_get(
        &self,
        ifindex: u32,
        nonce: [u8; GTPU_TRAFFIC_OBSERVATION_REDIRECT_NONCE_LEN],
    ) -> Result<Option<[u8; GTPU_SESSION_GROUP_ID_LEN]>, GtpuError>;

    /// Bind one redirect nonce to its group with BPF_NOEXIST.
    fn traffic_observation_redirect_put_noexist(
        &self,
        ifindex: u32,
        nonce: [u8; GTPU_TRAFFIC_OBSERVATION_REDIRECT_NONCE_LEN],
        group: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<(), GtpuError>;

    /// Remove a redirect authority only if it still has the exact group binding.
    fn traffic_observation_redirect_remove_exact(
        &self,
        ifindex: u32,
        nonce: [u8; GTPU_TRAFFIC_OBSERVATION_REDIRECT_NONCE_LEN],
        group: [u8; GTPU_SESSION_GROUP_ID_LEN],
    ) -> Result<bool, GtpuError>;

    /// Drain at most `budget` raw records from the single shared ring.
    fn traffic_observation_drain(
        &self,
        ifindex: u32,
        budget: usize,
    ) -> Result<EbpfTrafficObservationDrain, GtpuError>;

    /// Aggregate the complete per-CPU loss counter. A read error is fatal to
    /// proof authority; callers bracket every drain with this value.
    fn traffic_observation_loss(&self, ifindex: u32) -> Result<u64, GtpuError>;

    /// Read counters only after proving the live hooks and exact named pins.
    fn datapath_snapshot(&self, ifindex: u32) -> Result<EbpfGtpuDatapathSnapshot, GtpuError>;

    /// Read the single-slot uplink MTU policy value for a managed device.
    fn pmtu_policy_get(&self, ifindex: u32) -> Result<[u8; UPLINK_PMTU_VALUE_LEN], GtpuError>;
    /// Write the single-slot uplink MTU policy value for a managed device.
    ///
    /// The all-zero value is the explicit unset (legacy) state; only
    /// canonical policy bytes or zeros may be written.
    fn pmtu_policy_write(
        &self,
        ifindex: u32,
        value: [u8; UPLINK_PMTU_VALUE_LEN],
    ) -> Result<(), GtpuError>;

    /// Read the single current-schema marker slot for the TFT classifier.
    fn tft_schema_get(
        &self,
        ifindex: u32,
    ) -> Result<[u8; opc_gtpu_ebpf_common::TFT_CLASSIFIER_SCHEMA_VALUE_LEN], GtpuError>;

    /// Read one TFT classifier metadata value by its exact byte key.
    fn tft_meta_get(
        &self,
        ifindex: u32,
        key: [u8; TFT_CLASSIFIER_KEY_LEN],
    ) -> Result<Option<[u8; TFT_CLASSIFIER_META_VALUE_LEN]>, GtpuError>;

    /// Atomically create or replace one complete TFT classifier metadata value.
    fn tft_meta_put(
        &self,
        ifindex: u32,
        key: [u8; TFT_CLASSIFIER_KEY_LEN],
        value: [u8; TFT_CLASSIFIER_META_VALUE_LEN],
    ) -> Result<(), GtpuError>;

    /// Delete one TFT classifier metadata value; returns whether it existed.
    fn tft_meta_remove(
        &self,
        ifindex: u32,
        key: [u8; TFT_CLASSIFIER_KEY_LEN],
    ) -> Result<bool, GtpuError>;

    /// Enumerate the bounded raw filter records whose first classifier-key
    /// octets equal `classifier_key`. Malformed key/value bytes are preserved
    /// so the backend can classify them as indeterminate rather than overlook
    /// hostile retained map contents.
    fn tft_filter_inventory(
        &self,
        ifindex: u32,
        classifier_key: [u8; TFT_CLASSIFIER_KEY_LEN],
    ) -> Result<Vec<EbpfTftFilterRecord>, GtpuError>;

    /// Insert or replace one complete fixed-width TFT filter record.
    fn tft_filter_put(
        &self,
        ifindex: u32,
        key: [u8; TFT_CLASSIFIER_FILTER_KEY_LEN],
        value: [u8; TFT_CLASSIFIER_FILTER_VALUE_LEN],
    ) -> Result<(), GtpuError>;

    /// Delete one exact TFT filter record; returns whether it existed.
    fn tft_filter_remove(
        &self,
        ifindex: u32,
        key: [u8; TFT_CLASSIFIER_FILTER_KEY_LEN],
    ) -> Result<bool, GtpuError>;

    /// Report exact bounded occupancy/capacity before inactive-bank staging.
    fn tft_filter_capacity(&self, ifindex: u32) -> Result<EbpfTftFilterMapCapacity, GtpuError>;

    /// Derive opaque durable classifier ownership from the exact retained
    /// current graph and managed attachment identity.
    fn tft_authority(&self, ifindex: u32) -> Result<EbpfTftAuthority, GtpuError>;

    /// Return whether current program, held/pinned maps, TFT marker, and
    /// managed attachment identity are all simultaneously authoritative.
    fn tft_datapath_usable(&self, ifindex: u32) -> bool;

    /// Probe the environment for eBPF datapath readiness.
    fn probe_environment(&self) -> EbpfEnvironment;

    /// Return whether the target interface's live uplink filter is the exact
    /// loaded program and references the exact pinned DSCP map.
    fn dscp_datapath_usable(&self, ifindex: u32) -> bool;

    /// Return whether the target interface's live filters are the exact
    /// loaded programs and reference the complete source-port commit graph.
    fn source_port_datapath_usable(&self, ifindex: u32) -> bool;

    /// Return whether both live filters are the exact loaded programs and
    /// reference every exact pinned per-bearer mark map.
    fn bearer_mark_datapath_usable(&self, ifindex: u32) -> bool;

    /// Return whether the exact live downlink program and both endpoint-
    /// binding maps are present for the managed attachment.
    fn downlink_endpoint_binding_datapath_usable(&self, ifindex: u32) -> bool;

    /// Return whether the exact live uplink program and both MTU policy maps
    /// are present and the live policy is executable by tc.
    fn pmtu_datapath_usable(&self, ifindex: u32) -> bool;

    /// Return whether the exact live uplink program and both MTU policy maps
    /// can accept a canonical policy repair, independent of the current slot
    /// contents.
    fn pmtu_datapath_writable(&self, ifindex: u32) -> bool;

    /// Return whether readback can trust the exact programs, every named map,
    /// and the held reconciler lease for this managed device.
    fn pdp_readback_datapath_usable(&self, ifindex: u32) -> bool;

    /// Return whether PDP cleanup can safely mutate the held maps.
    ///
    /// Every named pin must still identify its exact held map. An ordinary
    /// attachment permits its exact hook or absence in each tc slot because
    /// removal only reduces reachability. A cleanup-only attachment requires
    /// both forwarding hooks to remain absent; any reappearance revokes its
    /// narrower authority.
    fn pdp_cleanup_datapath_usable(&self, ifindex: u32) -> bool;
}

#[derive(Debug, Default)]
pub(crate) struct EbpfTrafficObservationDrain {
    records: Vec<[u8; GTPU_TRAFFIC_OBSERVATION_EVENT_LEN]>,
    overflowed: bool,
}

#[derive(Clone)]
struct ManagedDevice {
    name: String,
    /// Legacy v5 IPv4 authority. Grouped attachments deliberately leave this
    /// absent even when their endpoint set contains IPv4, so no grouped graph
    /// can fall through the legacy single-address reconciliation path.
    local_ip: Option<Ipv4Addr>,
    grouped: Option<ManagedGroupedDevice>,
    /// True while the device is held under cleanup-only recovery authority:
    /// forwarding hooks are fenced and only exact readback/removal plus an
    /// explicit activation are authorized.
    cleanup_only: bool,
}

impl fmt::Debug for ManagedDevice {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ManagedDevice")
            .field("interface_identity", &"<redacted>")
            .field("legacy_ipv4", &self.local_ip.is_some())
            .field("grouped", &self.grouped)
            .field("cleanup_only", &self.cleanup_only)
            .finish()
    }
}

