    fn seed_managed_identity(
        backend: &EbpfGtpuDataplaneBackend,
        ifindex: u32,
        name: impl Into<String>,
    ) {
        backend.inner.devices.lock().unwrap().insert(
            ifindex,
            ManagedDevice {
                name: name.into(),
                local_ip: None,
                grouped: None,
                cleanup_only: false,
            },
        );
    }

    fn grouped_device_id(value: u8) -> GtpuSessionDeviceId {
        GtpuSessionDeviceId::new([value; GTPU_SESSION_GROUP_ID_LEN]).unwrap()
    }

    fn grouped_group_id(value: u8) -> opc_gtpu_ebpf_common::GtpuSessionGroupId {
        opc_gtpu_ebpf_common::GtpuSessionGroupId::new([value; GTPU_SESSION_GROUP_ID_LEN]).unwrap()
    }

    fn ipv6_local() -> Ipv6Addr {
        "2001:db8:10::1".parse().unwrap()
    }

    fn ipv6_peer() -> Ipv6Addr {
        "2001:db8:20::1".parse().unwrap()
    }

    fn ipv6_inner() -> Ipv6Addr {
        "2001:db8:100:1::1234".parse().unwrap()
    }

    fn grouped_device_request(
        name: &str,
        device_id: GtpuSessionDeviceId,
        endpoints: GtpuLocalEndpointSet,
    ) -> CreateGtpDeviceEndpointSetRequest {
        CreateGtpDeviceEndpointSetRequest::new(
            CreateGtpDeviceRequest::new(name),
            device_id,
            endpoints,
        )
        .unwrap()
    }

    fn grouped_v6_entry(local_teid: u32, peer_teid: u32, peer: Ipv6Addr) -> GtpuSessionEntry {
        GtpuSessionEntry::new(
            GtpPdpContext {
                local_teid: teid(local_teid),
                peer_teid: teid(peer_teid),
                ms_address: IpAddr::V6(ipv6_inner()),
                peer_address: IpAddr::V6(peer),
                link_ifindex: S2BU_IFINDEX,
                downlink_source_port_policy: crate::GtpuSourcePortPolicy::Any,
                gtp_version: GtpVersion::V1,
                bearer_mark: None,
                egress_dscp: Some(crate::DscpCodepoint::new(18).unwrap()),
                uplink_source_port_policy: crate::GtpuUplinkSourcePortPolicy::LegacyServicePort,
            },
            IpAddr::V6(ipv6_local()),
        )
        .unwrap()
    }

    fn grouped_v4_entry(local_teid: u32, peer_teid: u32) -> GtpuSessionEntry {
        GtpuSessionEntry::new(
            GtpPdpContext {
                local_teid: teid(local_teid),
                peer_teid: teid(peer_teid),
                ms_address: IpAddr::V4(Ipv4Addr::new(10, 45, 0, 2)),
                peer_address: IpAddr::V4(Ipv4Addr::new(192, 0, 2, 10)),
                link_ifindex: S2BU_IFINDEX,
                downlink_source_port_policy: crate::GtpuSourcePortPolicy::Any,
                gtp_version: GtpVersion::V1,
                bearer_mark: None,
                egress_dscp: None,
                uplink_source_port_policy: crate::GtpuUplinkSourcePortPolicy::LegacyServicePort,
            },
            IpAddr::V4(Ipv4Addr::new(192, 0, 2, 1)),
        )
        .unwrap()
    }

    fn grouped_entry_for_addresses(
        inner: IpAddr,
        peer_outer: IpAddr,
        local_outer: IpAddr,
        local_teid: u32,
        peer_teid: u32,
        bearer_mark: Option<u32>,
    ) -> GtpuSessionEntry {
        GtpuSessionEntry::new(
            GtpPdpContext {
                local_teid: teid(local_teid),
                peer_teid: teid(peer_teid),
                ms_address: inner,
                peer_address: peer_outer,
                link_ifindex: S2BU_IFINDEX,
                downlink_source_port_policy: crate::GtpuSourcePortPolicy::Any,
                gtp_version: GtpVersion::V1,
                bearer_mark: bearer_mark.and_then(GtpBearerMark::new),
                egress_dscp: None,
                uplink_source_port_policy: crate::GtpuUplinkSourcePortPolicy::LegacyServicePort,
            },
            local_outer,
        )
        .unwrap()
    }

    fn grouped_group(
        id: u8,
        device_id: GtpuSessionDeviceId,
        entries: Vec<GtpuSessionEntry>,
    ) -> GtpuSessionGroup {
        GtpuSessionGroup::new(grouped_group_id(id), device_id, entries).unwrap()
    }

    fn fresh_group_request(
        backend: &EbpfGtpuDataplaneBackend,
        group: GtpuSessionGroup,
    ) -> GtpuSessionGroupReconcileRequest {
        let admission = fresh_group_admission(&group);
        let binding = admission.binding();
        if backend
            .ensure_selector_namespace_binding_sync(binding)
            .is_err()
        {
            backend.provision_selector_namespace_sync(binding).unwrap();
        }
        GtpuSessionGroupReconcileRequest::new(group, admission).unwrap()
    }

    fn unbound_fresh_group_request(group: GtpuSessionGroup) -> GtpuSessionGroupReconcileRequest {
        let admission = fresh_group_admission(&group);
        GtpuSessionGroupReconcileRequest::new(group, admission).unwrap()
    }

    fn fresh_group_admission(group: &GtpuSessionGroup) -> crate::GtpuSessionSelectorAdmission {
        let namespace = crate::selector_namespace::TestGtpuSessionSelectorNamespaceAuthority::new(
            crate::InMemoryGtpuSessionSelectorNamespaceStore::default(),
            [0x53; 32],
            32,
        );
        namespace.claim(group, None).unwrap()
    }

    fn retiring_group_admission(group: &GtpuSessionGroup) -> crate::GtpuSessionSelectorAdmission {
        let namespace = crate::selector_namespace::TestGtpuSessionSelectorNamespaceAuthority::new(
            crate::InMemoryGtpuSessionSelectorNamespaceStore::default(),
            [0x53; 32],
            32,
        );
        let installing = namespace.claim(group, None).unwrap();
        let active = namespace.activate(installing).unwrap();
        namespace.begin_retire(active).unwrap().into_inner()
    }

    fn reused_group_admission(
        retired: &GtpuSessionGroup,
        desired: &GtpuSessionGroup,
        proof: &GtpuSessionSelectorReuseProof,
    ) -> crate::GtpuSessionSelectorAdmission {
        let namespace = crate::selector_namespace::TestGtpuSessionSelectorNamespaceAuthority::new(
            crate::InMemoryGtpuSessionSelectorNamespaceStore::default(),
            [0x53; 32],
            32,
        );
        let installing = namespace.claim(retired, None).unwrap();
        let active = namespace.activate(installing).unwrap();
        let retiring = namespace.begin_retire(active).unwrap();
        namespace.finish_retire(retiring).unwrap();
        namespace.claim_reused(desired, proof).unwrap()
    }

    fn reused_group_request(
        retired: GtpuSessionGroup,
        desired: GtpuSessionGroup,
        proof: GtpuSessionSelectorReuseProof,
    ) -> GtpuSessionGroupReconcileRequest {
        let admission = reused_group_admission(&retired, &desired, &proof);
        GtpuSessionGroupReconcileRequest::new_reused(desired, admission, proof).unwrap()
    }

    fn grouped_rekey_pair(
        device_id: GtpuSessionDeviceId,
        group_id: u8,
    ) -> (GtpuSessionGroup, GtpuSessionGroup) {
        let base = grouped_group(
            group_id,
            device_id,
            vec![grouped_entry_for_addresses(
                IpAddr::V6("2001:db8:100:1::1234".parse().unwrap()),
                IpAddr::V6("2001:db8:20::1".parse().unwrap()),
                IpAddr::V6(ipv6_local()),
                0x1100_0001,
                0x2100_0001,
                Some(0x41),
            )],
        );
        let desired = grouped_group(
            group_id,
            device_id,
            vec![grouped_entry_for_addresses(
                IpAddr::V6("2001:db8:100:2::5678".parse().unwrap()),
                IpAddr::V6("2001:db8:30::2".parse().unwrap()),
                IpAddr::V6(ipv6_local()),
                0x1200_0002,
                0x2200_0002,
                Some(0x42),
            )],
        );
        (base, desired)
    }

