        assert_eq!(state.pdr, before.1);
        assert_eq!(state.downlink_binding, before.2);
        assert_eq!(state.sport, before.3);
        assert_eq!(state.schema, before.4);
        assert_eq!(state.pmtu_policy, before.5);
